    int minimumPairRemoval(vector<int>& nums) {
        auto isSorted = [](const vector<int>& a) {
            for (size_t i = 0; i + 1 < a.size(); ++i) {
                if (a[i] > a[i + 1]) return false;
            }
            return true;
        };

        int ops = 0;
        vector<int> curr = nums;
        while (!isSorted(curr)) {
            long long minSum = LLONG_MAX;
            int minIdx = -1;
            for (size_t i = 0; i + 1 < curr.size(); ++i) {
                long long s = (long long)curr[i] + curr[i + 1];
                if (s < minSum) {
                    minSum = s;
                    minIdx = i;
                }
