import java.util.*;

class Solution {
    public int minimumPairRemoval(int[] nums) {
        List<Integer> list = new ArrayList<>();
        for (int v : nums) list.add(v);

        int ops = 0;
        while (!isSorted(list)) {
            long minSum = Long.MAX_VALUE;
            int minIdx = -1;
            for (int i = 0; i + 1 < list.size(); i++) {
                long s = (long) list.get(i) + list.get(i + 1);
                if (s < minSum) {
                    minSum = s;
                    minIdx = i;
                }
            }
            list.set(minIdx, (int) minSum);
            list.remove(minIdx + 1);
            ops++;
        }
        return ops;
    }

    private boolean isSorted(List<Integer> list) {
        for (int i = 0; i + 1 < list.size(); i++) {
            if (list.get(i) > list.get(i + 1)) return false;
        }
        return true;
    }
}

var minimumPairRemoval = function(nums) {
    const isSorted = arr => {
        for (let i = 0; i + 1 < arr.length; i++) {
            if (arr[i] > arr[i + 1]) return false;
        }
        return true;
    };

    let ops = 0;
    const curr = [...nums];
    while (!isSorted(curr)) {
        let minSum = Infinity;
        let minIdx = -1;
        for (let i = 0; i + 1 < curr.length; i++) {
            const s = curr[i] + curr[i + 1];
            if (s < minSum) {
                minSum = s;
                minIdx = i;
            }
        }
        curr[minIdx] = minSum;
        curr.splice(minIdx + 1, 1);
        ops++;
    }
    return ops;
};
